-- Participant feedback opens at submission close. Staff timing overrides remain guarded.
-- Stored content, old policy fields and immutable result snapshots are preserved.
DROP TRIGGER community_submission_vote_window;
DROP TRIGGER legacy_submission_vote_window;
CREATE TRIGGER community_submission_vote_window BEFORE INSERT ON project_upvotes WHEN NOT EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)>=julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)<julianday(json_extract(policy,'$.submissionClose'))) BEGIN SELECT RAISE(ABORT,'VOTING_CLOSED'); END;
CREATE TRIGGER legacy_submission_vote_window BEFORE INSERT ON votes WHEN NOT EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)>=julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)<julianday(json_extract(policy,'$.submissionClose'))) BEGIN SELECT RAISE(ABORT,'VOTING_CLOSED'); END;
DROP TRIGGER feedback_guard;
CREATE TRIGGER feedback_guard BEFORE INSERT ON feedback BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM memberships WHERE user_id=NEW.author_id AND team_id=NEW.team_id) THEN RAISE(ABORT,'OWN_TEAM') END;
 SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-feedback:'||json_array(NEW.author_id,NEW.team_id,NEW.updated_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT EXISTS(SELECT 1 FROM check_ins c JOIN users u ON u.id=c.user_id JOIN registrations r ON r.email=u.email WHERE c.user_id=NEW.author_id AND r.status='approved') THEN RAISE(ABORT,'CHECKIN_REQUIRED') END;
 SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-feedback:'||json_array(NEW.author_id,NEW.team_id,NEW.updated_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT (EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.updated_at)>=julianday(json_extract(policy,'$.submissionClose')))) THEN RAISE(ABORT,'FEEDBACK_NOT_OPEN') END;
END;
CREATE TRIGGER feedback_guard_update BEFORE UPDATE OF text,updated_at ON feedback BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM memberships WHERE user_id=NEW.author_id AND team_id=NEW.team_id) THEN RAISE(ABORT,'OWN_TEAM') END;
 SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-feedback:'||json_array(NEW.author_id,NEW.team_id,NEW.updated_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT EXISTS(SELECT 1 FROM check_ins c JOIN users u ON u.id=c.user_id JOIN registrations r ON r.email=u.email WHERE c.user_id=NEW.author_id AND r.status='approved') THEN RAISE(ABORT,'CHECKIN_REQUIRED') END;
 SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-feedback:'||json_array(NEW.author_id,NEW.team_id,NEW.updated_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT (EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.updated_at)>=julianday(json_extract(policy,'$.submissionClose')))) THEN RAISE(ABORT,'FEEDBACK_NOT_OPEN') END;
END;
CREATE TRIGGER community_feedback_after_close BEFORE INSERT ON project_comments WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-comment:'||json_array(NEW.author_id,NEW.project_id,NEW.created_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT (EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)>=julianday(json_extract(policy,'$.submissionClose')))) BEGIN SELECT RAISE(ABORT,'FEEDBACK_NOT_OPEN'); END;
CREATE TRIGGER community_feedback_after_close_update BEFORE UPDATE OF body,created_at ON project_comments WHEN NOT (EXISTS(SELECT 1 FROM write_guards g JOIN users u ON u.id=NEW.author_id LEFT JOIN portal_roles r ON r.user_id=u.id WHERE g.token='staff-comment:'||json_array(NEW.author_id,NEW.project_id,NEW.created_at) AND g.valid=1 AND (lower(u.email)='connectwithparam.30@gmail.com' OR COALESCE(r.role,u.role)='admin') AND NOT EXISTS(SELECT 1 FROM record_removals x WHERE x.kind='participant' AND x.target_id=u.id AND x.active=1))) AND NOT (EXISTS(SELECT 1 FROM event_settings WHERE id=1 AND julianday(json_extract(policy,'$.submissionClose'))>julianday(json_extract(policy,'$.submissionOpen')) AND julianday(NEW.created_at)>=julianday(json_extract(policy,'$.submissionClose')))) BEGIN SELECT RAISE(ABORT,'FEEDBACK_NOT_OPEN'); END;
